/**
 * Request body sent to the API to register a new reservation.
 *
 * @remarks
 * The id is not included because it is generated by JSON Server.
 *
 * @author José Santana
 */
export interface CreateReservationRequest {
  sportsCenterId: number;
  activityType: string;
  participantName: string;
  participants: number;
  weatherTemperature: number;
  reservedAt: string;
}
